// PREREQUISITI:
// 1. Crea risorsa "Document Intelligence" su Azure Portal (tier Free = 500 pag/mese)
// 2. In n8n, aggiungi una credenziale "Header Auth" chiamata "Azure Doc Intelligence":
//    - Header Name: Ocp-Apim-Subscription-Key
//    - Header Value: la tua API key
// 3. Sostituisci AZURE_DOC_INTEL_ENDPOINT qui sotto col tuo endpoint reale
//
// COME FUNZIONA:
// 1. Scarica il PDF come buffer binario da Personio
// 2. Lo invia ad Azure Document Intelligence (modello prebuilt-read)
// 3. Polling fino a completamento (Azure lo processa async)
// 4. Estrae il testo e lo aggiunge al profilo candidato
// ============================================================

const AZURE_DOC_INTEL_ENDPOINT = 'https://YOUR-RESOURCE.cognitiveservices.azure.com';
const AZURE_DOC_INTEL_KEY = 'YOUR_API_KEY'; // Oppure usa $credentials se configuri Header Auth
const MAX_CANDIDATES = 200;
const CV_CHAR_LIMIT = 4000; // Tronca CV lunghi per non esplodere il prompt AI

const authToken = $('Personio Auth').first().json.data.token;
const firstBatch = $('Get Applications').first().json;

let allApplications = firstBatch.data || [];
const total = firstBatch.metadata?.total_elements || allApplications.length;

// --- PAGINAZIONE ---
if (total > 100) {
  let offset = 100;
  while (offset < total && allApplications.length < MAX_CANDIDATES) {
    try {
      const response = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://api.personio.de/v2/recruiting/applications',
        headers: { 'Authorization': `Bearer ${authToken}`, 'Accept': 'application/json' },
        qs: { limit: 100, offset }
      });
      if (response.data?.length > 0) {
        allApplications = allApplications.concat(response.data);
      } else break;
      offset += 100;
    } catch (e) { break; }
  }
}
allApplications = allApplications.slice(0, MAX_CANDIDATES);

// --- DEDUPLICAZIONE: tieni l'applicazione più recente per email ---
const seen = new Map();
for (const app of allApplications) {
  const attrs = app.attributes || {};
  const key = attrs.email?.value || String(app.id);
  const date = attrs.application_date?.value || '1970-01-01';
  if (!seen.has(key) || date > seen.get(key).date) {
    seen.set(key, { app, date });
  }
}
const uniqueApps = [...seen.values()].map(v => v.app);

// =============================================================
// FUNZIONE: Estrai testo da PDF via Azure Document Intelligence
// =============================================================
async function extractTextFromPdf(pdfBuffer) {
  // Step 1: Invia il PDF per l'analisi (async — Azure restituisce un URL di polling)
  const analyzeResponse = await this.helpers.httpRequest({
    method: 'POST',
    url: `${AZURE_DOC_INTEL_ENDPOINT}/documentintelligence/documentModels/prebuilt-read:analyze?api-version=2024-11-30`,
    headers: {
      'Ocp-Apim-Subscription-Key': AZURE_DOC_INTEL_KEY,
      'Content-Type': 'application/pdf'
    },
    body: pdfBuffer,
    returnFullResponse: true,
    encoding: null // invia bytes grezzi
  });

  // Step 2: Ottieni l'URL di polling dall'header "Operation-Location"
  const operationUrl = analyzeResponse.headers?.['operation-location'];
  if (!operationUrl) {
    throw new Error('Azure non ha restituito operation-location');
  }

  // Step 3: Polling fino a completamento (max 30 secondi)
  let result = null;
  for (let attempt = 0; attempt < 15; attempt++) {
    await new Promise(r => setTimeout(r, 2000));

    const pollResponse = await this.helpers.httpRequest({
      method: 'GET',
      url: operationUrl,
      headers: {
        'Ocp-Apim-Subscription-Key': AZURE_DOC_INTEL_KEY
      }
    });

    if (pollResponse.status === 'succeeded') {
      result = pollResponse;
      break;
    } else if (pollResponse.status === 'failed') {
      throw new Error('Azure Document Intelligence: analisi fallita');
    }
    // 'running' → continua polling
  }

  if (!result) {
    throw new Error('Azure Document Intelligence: timeout dopo 30s');
  }

  // Step 4: Estrai il testo da tutte le pagine
  const pages = result.analyzeResult?.pages || [];
  const lines = [];
  for (const page of pages) {
    for (const line of (page.lines || [])) {
      lines.push(line.content);
    }
  }

  // Fallback: se pages non ha lines, prova content diretto
  if (lines.length === 0 && result.analyzeResult?.content) {
    return result.analyzeResult.content.substring(0, CV_CHAR_LIMIT);
  }

  return lines.join('\n').substring(0, CV_CHAR_LIMIT);
}

// --- COSTRUISCI PROFILO + FETCH CV ---
const candidates = [];
for (let i = 0; i < uniqueApps.length; i++) {
  const app = uniqueApps[i];
  const attrs = app.attributes || {};
  const firstName = attrs.first_name?.value || '';
  const lastName = attrs.last_name?.value || '';
  const name = `${firstName} ${lastName}`.trim() || `Candidate ${i + 1}`;

  const profileParts = [];
  if (attrs.job_position?.value) profileParts.push(`Position applied: ${attrs.job_position.value}`);
  if (attrs.application_date?.value) profileParts.push(`Date: ${attrs.application_date.value}`);
  if (attrs.message?.value) profileParts.push(`Cover letter: ${attrs.message.value}`);

  const skipFields = new Set(['first_name', 'last_name', 'job_position', 'application_date', 'id', 'message', 'email']);
  const customFields = Object.entries(attrs)
    .filter(([key, val]) => !skipFields.has(key) && val?.value)
    .map(([key, val]) => `${key}: ${typeof val.value === 'object' ? JSON.stringify(val.value) : val.value}`)
    .join('\n');
  if (customFields) profileParts.push(customFields);

  // --- FETCH CV VIA AZURE DOCUMENT INTELLIGENCE ---
  let cvText = '';
  try {
    const docs = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://api.personio.de/v1/recruiting/applications/${app.id}/documents`,
      headers: { 'Authorization': `Bearer ${authToken}`, 'Accept': 'application/json' }
    });

    if (docs.data?.length > 0) {
      // Prendi solo il primo documento (tipicamente il CV)
      const doc = docs.data[0];
      const downloadUrl = doc.attributes?.url?.value || doc.url || '';

      if (downloadUrl) {
        try {
          // Scarica PDF come buffer binario (NON utf-8!)
          const pdfBuffer = await this.helpers.httpRequest({
            method: 'GET',
            url: downloadUrl,
            headers: { 'Authorization': `Bearer ${authToken}` },
            encoding: null,          // <-- CRITICO: binario, non utf-8
            returnFullResponse: false
          });

          if (pdfBuffer && pdfBuffer.length > 100) {
            const extractedText = await extractTextFromPdf.call(this, pdfBuffer);
            if (extractedText && extractedText.length > 50) {
              cvText = 'CV Content:\n' + extractedText;
            }
          }
        } catch (dlError) {
          cvText = `[CV download/parse failed: ${dlError.message}]`;
        }
      }
    }
  } catch (e) {
    // Documents endpoint non accessibile — continua senza CV
  }

  if (cvText) profileParts.push(cvText);

  candidates.push({
    json: {
      CandidateID: app.id || i + 1,
      Name: name,
      ProfileText: profileParts.join('\n') || 'No profile data available',
      _hasCv: cvText.startsWith('CV Content') // flag utile per debug
    }
  });

  // Throttle: pausa ogni 5 candidati (Azure ha rate limits)
  if (i < uniqueApps.length - 1 && i % 5 === 4) {
    await new Promise(r => setTimeout(r, 1000));
  }
}

return candidates;

// Raggruppa candidati in batch da 5 per ridurre chiamate API
const allCandidates = $input.all().map(i => i.json);
const BATCH_SIZE = 5;
const batches = [];

for (let i = 0; i < allCandidates.length; i += BATCH_SIZE) {
  batches.push({
    json: {
      batch_index: Math.floor(i / BATCH_SIZE),
      candidates: allCandidates.slice(i, i + BATCH_SIZE),
      total_batches: Math.ceil(allCandidates.length / BATCH_SIZE)
    }
  });
}

return batches;

// Parse risposta AI batch — estrai array di evaluations
let responseText = '';
try {
  responseText = $input.item.json.choices?.[0]?.message?.content || '';
} catch(e) { responseText = ''; }

if (!responseText) {
  return [{ json: { candidateId: 0, name: 'API_ERROR', score: 0, summary: 'Batch skipped — API error' } }];
}

let result;
try {
  result = JSON.parse(responseText);
} catch(e) {
  const clean = responseText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  try { result = JSON.parse(clean); } catch(e2) {
    // Ultimo tentativo: estrai primo oggetto JSON
    const match = clean.match(/\{[\s\S]*\}/);
    if (match) {
      try { result = JSON.parse(match[0]); } catch(e3) {
        return [{ json: { candidateId: 0, name: 'PARSE_ERROR', score: 0, summary: 'Could not parse batch response' } }];
      }
    } else {
      return [{ json: { candidateId: 0, name: 'PARSE_ERROR', score: 0, summary: 'No JSON found in response' } }];
    }
  }
}

const evaluations = result.evaluations || [];
if (evaluations.length === 0) {
  return [{ json: { candidateId: 0, name: 'EMPTY_RESULT', score: 0, summary: 'No evaluations in batch' } }];
}

// Flatten: un item per candidato
return evaluations.map(e => ({ json: e }));

// Raccogli TUTTI i risultati dal loop (executionOrder v1 → .all() funziona)
const allItems = $('Parse Pre-Screen').all().map(i => i.json);

const minScore = $('Settings').first().json.min_score || 60;
const topN = $('Settings').first().json.top_n || 5;
const jdText = $('Settings').first().json.jd_text;
const jdTitle = $('Settings').first().json.jd_title;

// Filtra errori di parsing (candidateId === 0)
const valid = allItems.filter(c => c.candidateId > 0);

// Safety check CORRETTO: non esplode con 1 candidato, ma avvisa se 0
if (valid.length === 0) {
  return [{
    json: {
      total_screened: 0,
      above_threshold: 0,
      no_candidates_above_threshold: true,
      jd_text: jdText,
      jd_title: jdTitle,
      candidate_list: 'Nessun candidato valutato con successo. Controllare i log delle chiamate API.',
      top_n: topN,
      execution_time: new Date().toISOString(),
      _warning: 'Zero valid candidates — check API responses'
    }
  }];
}

const filtered = valid
  .filter(c => c.score >= minScore)
  .sort((a, b) => b.score - a.score);

// Passa top_n + 10 al ranking per dare margine all'AI
const topCandidates = filtered.slice(0, Math.min(topN + 10, filtered.length));

const candidateList = topCandidates.map(c =>
  `ID:${c.candidateId} | ${c.name} | Pre-Screen Score: ${c.score}/100 | ${c.summary}`
).join('\n\n');

return [{
  json: {
    total_screened: valid.length,
    above_threshold: filtered.length,
    no_candidates_above_threshold: filtered.length === 0,
    jd_text: jdText,
    jd_title: jdTitle,
    candidate_list: candidateList || 'Nessun candidato sopra la soglia di ' + minScore,
    top_n: topN,
    execution_time: new Date().toISOString()
  }
}];

const responseText = $input.item.json.choices?.[0]?.message?.content || '';

let result;
try {
  result = JSON.parse(responseText);
} catch(e) {
  const clean = responseText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  try { result = JSON.parse(clean); } catch(e2) {
    const match = clean.match(/\{[\s\S]*\}/);
    if (match) {
      try { result = JSON.parse(match[0]); } catch(e3) {
        throw new Error('Impossibile parsare il ranking finale: ' + clean.substring(0, 300));
      }
    } else {
      throw new Error('Nessun JSON nel ranking finale: ' + clean.substring(0, 300));
    }
  }
}

const rankings = result.top_candidates || [];
const stats = $('Collect & Filter').first().json;

return rankings.map(r => ({
  json: {
    Rank: r.rank,
    CandidateID: r.CandidateID,
    Name: r.Name,
    'Match Score': r.match_score,
    Reasoning: r.reasoning,
    'Interview Questions': (r.interview_questions || []).join(' | '),
    Position: stats.jd_title,
    'Total Screened': stats.total_screened,
    'Above Threshold': stats.above_threshold,
    Timestamp: stats.execution_time
  }
}));

const stats = $('Collect & Filter').first().json;
const rankings = $input.all().map(i => i.json);

return [{
  json: {
    Timestamp: stats.execution_time,
    Position: stats.jd_title,
    'Total Screened': stats.total_screened,
    'Above Threshold': stats.above_threshold,
    'Top Candidate': rankings.length > 0 ? rankings[0].Name : 'N/A',
    'Top Score': rankings.length > 0 ? rankings[0]['Match Score'] : 'N/A',
    'Candidates Ranked': rankings.length,
    'Min Score Threshold': $('Settings').first().json.min_score
  }
}];

const stats = $('Collect & Filter').first().json;
const rankings = $('Parse Final Ranking').all().map(i => i.json);

const topList = rankings.slice(0, 5).map(r =>
  `${r.Rank}. ${r.Name} — Score: ${r['Match Score']}/100`
).join('\n');

const message = `✅ *Screening completato: ${stats.jd_title}*\n\n` +
  `Candidati analizzati: ${stats.total_screened}\n` +
  `Sopra soglia: ${stats.above_threshold}\n\n` +
  `*Top ${Math.min(5, rankings.length)} candidati:*\n${topList}\n\n` +
  `Dettagli completi nel Google Sheet.`;

return [{ json: { text: message } }];

const stats = $('Collect & Filter').first().json;

const message = `⚠️ *Errore nel ranking finale: ${stats.jd_title}*\n\n` +
  `Il pre-screening è stato completato (${stats.total_screened} candidati analizzati, ${stats.above_threshold} sopra soglia), ` +
  `ma il ranking finale ha fallito.\n\n` +
  `I risultati del pre-screen sono disponibili nei log. Ritentare l'esecuzione o verificare la configurazione Azure OpenAI.\n\n` +
  `Timestamp: ${stats.execution_time}`;

return [{ json: { text: message } }];

const stats = $('Collect & Filter').first().json;

const message = `ℹ️ *Nessun candidato sopra soglia: ${stats.jd_title}*\n\n` +
  `Candidati analizzati: ${stats.total_screened}\n` +
  `Nessuno ha superato la soglia minima di ${$('Settings').first().json.min_score}/100.\n\n` +
  `Suggerimento: abbassare la soglia o rivedere la job description.`;

return [{ json: { text: message } }];
